// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint256 blockNum) public {
        vm.assume(amount == 10 ether);
        vm.assume(blockNum > 0);
        vm.roll(blockNum);
        vm.warp(block.timestamp + 1);
        address sender = address(0x1234);
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(ok);
        if (blockNum % 15 != 0) {
            assertTrue(address(c).balance == 10 ether);
        } else {
            assertTrue(address(c).balance == 0);
        }
    }
}
